const n=["Tools","Moving around","Items","Ink","Talking"],t=[{keys:["V"],does:"Select",group:"Tools"},{keys:["H","Space"],does:"Hand — drag the canvas",group:"Tools",note:"Holding Space borrows it; let go and your tool comes back"},{keys:["Z"],does:"Zoom — click an item to fit it, or drag a region",group:"Tools",note:"Tap to keep it, hold to borrow it"},{keys:["P"],does:"Pen — draw on the canvas",group:"Tools",note:"HOLD P and everything you draw is ONE drawing, however long you take between strokes"},{keys:["T"],does:"Text — click the canvas and type",group:"Tools",note:"double-click a text node to re-word it; ⌘Enter or click away to commit"},{keys:["C"],does:"Comment — click anywhere to start a thread",group:"Tools"},{keys:["⇧C"],does:"Comment on the selection",group:"Talking",note:"Anchored to the item, so the thread rides it when somebody moves it — and @-mentioning an agent there wakes it, the same as any other thread"},{keys:["Esc"],does:"Back out: leave full screen, stop watching, close a popover, drop the tool, deselect",group:"Tools",note:"One layer per press, outermost first — and how you get back to Select"},{keys:["⌘+","⌘−"],does:"Zoom in and out",group:"Moving around",note:"The canvas, never the browser"},{keys:["F","⇧2"],does:"Fit the selection",group:"Moving around",note:"With nothing selected, fits everything"},{keys:["⌘0","0","⇧1"],does:"Fit everything",group:"Moving around"},{keys:["W"],does:"Workbench — the agent room",group:"Moving around",note:"Who is here to work and what each is doing, the main thread beside them, and one item on a stage. A single selection comes along as the stage's focus; Esc steps back out"},{keys:["⇧0"],does:"Actual size (100%)",group:"Moving around"},{keys:["⌘O"],does:"Switch canvas",group:"Moving around",note:"The canvases you were on lately first, then the rest by activity; type a few letters to find one. Also ⌘K → Switch canvas…, or the ⌄ beside the canvas's name"},{keys:["⌥A"],does:"Include archived canvases",group:"Moving around",note:"In the switcher, when anything is archived. For this opening only: it starts at the canvases in the list every time, the way `canvas list` does without --with-archived"},{keys:["⌘←","⌘→","⌘↑","⌘↓"],does:"Jump to the nearest item that way",group:"Moving around",note:"Only items clear of the edge you leave — something overlapping you is beside you, not above it. In full screen the next item opens full screen too: a row of screens is a slideshow"},{keys:["←","→","↑","↓","PgUp","PgDn"],does:"Flip through the slides",group:"Moving around",note:"Full screen only. Items marked 🎬 (right-click → Make this a slide) are the deck, in reading order; with none marked, every item is. Page Up/Down flip too, so a presenter's clicker works"},{keys:["N"],does:"Speaker notes, in full screen",group:"Moving around"},{keys:["Scroll","Pinch"],does:"Pan and zoom",group:"Moving around"},{keys:["⌘G"],does:"Group selection",group:"Items",note:"Wrap selected roots in a named frame, preserving their arrangement"},{keys:["⌘⇧G"],does:"Ungroup",group:"Items",note:"Dissolve the selected group frames and preserve their members"},{keys:["⇧F10"],does:"Open selection menu",group:"Items",note:"The Menu key also opens it; arrows move and Enter chooses"},{keys:["←","→","↑","↓"],does:"Nudge the selection",group:"Items"},{keys:["⇧-drag"],does:"Snap harder to the guides",group:"Items",note:"Blue says aligned; purple says the gaps match"},{keys:["F2","Double-click the name"],does:"Rename",note:"The file follows the title",group:"Items"},{keys:["S"],does:"Show the version stack",group:"Items",note:"On an item with more than one version. Escape or S again closes it"},{keys:["⇧F"],does:"Fit the item to its content",group:"Items",note:"F fits the view to an item; ⇧F fits the item to what is in it. Several at once are settled so nothing overlaps"},{keys:["⇧D"],does:"Download",group:"Items",note:"The item's current version, under the filename it carries — the one the version stack and a rename both follow"},{keys:["Delete","Backspace"],does:"Move the selection to the trash",group:"Items",note:"One undo for the whole selection"},{keys:["⌘Z","⌘⇧Z"],does:"Undo and redo",note:"Yours, not everyone's",group:"Items"},{keys:["⌘C"],does:"Copy the selection",group:"Items",note:"The arrangement is kept, so a row pastes as a row — and the clipboard survives moving to another canvas, which is how you take things between them"},{keys:["⌘V"],does:"Paste",group:"Items",note:"Onto this canvas or another one. One undo takes the whole paste back"},{keys:["Scroll a selected item"],does:"Its content moves, not the canvas",group:"Items",note:"Only the wheel is handed over, so a drag still moves it. A page in a frame has to be entered first"},{keys:["Double-click an item"],does:"Step inside it: scroll it, click its links",group:"Items",note:"Inline, without leaving the canvas. Enter gives it the whole screen instead"},{keys:["Enter"],does:"Open the selection full screen",group:"Items",note:"On a group, enter its scope instead. Otherwise the address bar holds the screen you are on; Esc returns to the canvas"},{keys:["⌥-click"],does:"Reach the item underneath",group:"Items"},{keys:["Drag a box"],does:"Select several",group:"Items"},{keys:["⌘Z"],does:"Take back the last stroke",note:"While the ink is still wet",group:"Ink"},{keys:["⏎"],does:"Settle the ink into an item now",note:"Rather than waiting out the pause",group:"Ink"},{keys:["Draw over an item"],does:"Annotate it",note:"The mark travels with what it marks",group:"Ink"},{keys:["⌘K"],does:"Open the launcher: fit, arm a tool, open a panel, switch canvas, or ask an agent",group:"Talking",note:"Type a few letters and press Enter. A slash command from here opens the Chat with it typed, ready for the rest"},{keys:["⌘J"],does:"Open or close the Chat",group:"Talking",note:"Shut, the rail is a 48px strip: what you have not read, and which agents are working"},{keys:["⏎"],does:"Send it",group:"Talking",note:"⇧⏎ makes a new line instead; the composer grows to hold it and drops back to one line once sent"},{keys:["⌘⏎"],does:"Send the comment you are writing",group:"Talking",note:"Works from a reply box too, where ⏎ is a new line"},{keys:["@"],does:"Address someone",note:"They wake for it",group:"Talking"},{keys:["#"],does:"Point at an item",note:"It rides along as a card",group:"Talking"},{keys:["/"],does:"Signal on your cursor, or ask for a known piece of work",group:"Talking",note:"On the canvas, type a short message in place of your name for 20s (Esc clears); at the start of a message, opens slash commands"},{keys:["?"],does:"This list",group:"Talking"}];function a(e){return t.filter(o=>o.group===e)}function r(e){return t.find(s=>s.does===e)?.keys[0]??null}export{t as S,n as a,r as k,a as s};
